import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十九卦 蹇 水山蹇 坎上艮下","description":"周易 - 第三十九卦 蹇 水山蹇 坎上艮下","frontmatter":{"title":"第三十九卦 蹇 水山蹇 坎上艮下","description":"周易 - 第三十九卦 蹇 水山蹇 坎上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/040.md","filePath":"zh/classics/zhouyi/040.md"}'),l={name:"zh/classics/zhouyi/040.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利西南，不利东北；利见大人，贞吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>蹇，难也，险在前也。见险而能止，知矣哉！蹇利西南，往得中也；不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山上有水，蹇；君子以反身修德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>往蹇，来誉。象曰：往蹇来誉，宜待也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>王臣蹇蹇，匪躬之故。象曰：王臣蹇蹇，终无尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>往蹇来反。象曰：往蹇来反，内喜之也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>往蹇来连。象曰：往蹇来连，当位实也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>大蹇朋来。象曰：大蹇朋来，以中节也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>往蹇来硕，吉；利见大人。象曰：往蹇来硕，志在内也。利见大人，以从贵也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
